use moloch_live_runtime::{execution_router::*,source_innovation::{Kind,Model,Observation,evaluate},value_surface::sha256};
#[path="support/value_surface_fixture.rs"]mod support;
use support::*;
fn policy()->Policy{Policy{strategy_sha256:"a".repeat(64),order_expiry_ms:NOW+30000,model_uncertainty_per_share:1000,terminal_tail_charge_per_share:1000,write_charge_per_order:100,capital_charge_per_million_unit_ms:0}}
#[test]fn reviewed_terminal_candidates_remain_available_without_relabeling_liquidation_model_as_terminal(){let f=F::new();let s=f.bound(NOW).unwrap();let head=f.bank.durable_head();let r=terminal(&f.bank,&f.scope,&s,3,&policy(),NOW).unwrap();assert_eq!(r.lane,Lane::TerminalValue);assert_eq!(r.horizon_ms,300000);assert_eq!(r.candidates.len(),3);assert!(r.holding_policy_compatible);assert!(!r.prospective_economic_gate_qualified);assert!(!r.execution_authority);assert!(r.candidates.iter().all(|a|a.owned_execution_model.is_none()&&a.execution_model_reason.as_deref()==Some("ROUTER_TERMINAL_TARGET_NOT_OWNED_LIQUIDATION")&&a.qualified_joint_score_per_requested_share.is_none()));assert!(r.candidates.iter().all(|a|a.conditional_value_surplus>0&&a.scheduled_capital_time_unit_ms==a.gross_funding*300000));assert_eq!(f.bank.durable_head(),head);}
fn innovation(f:&F,s:&moloch_live_runtime::value_surface::BoundSurface)->(Model,moloch_live_runtime::source_innovation::Signal){let c=&s.contracts()[3];let m=Model{version:1,kind:Kind::ExternalCatchUp,source:"synthetic external fixture".into(),source_contract_root_sha256:"a".repeat(64),target_exchange_id:c.exchange_id.clone(),target_contract_root_sha256:c.official_root_sha256.clone(),training_source_sha256:"b".repeat(64),training_end_ms:NOW-1000000,validation_end_ms:NOW-900000,created_at_ms:NOW-800000,expires_at_ms:NOW+10000,maximum_source_age_ms:10000,maximum_baseline_age_ms:10000,half_life_ms:1000,prediction_horizon_ms:1000,minimum_independent_clusters:3,independent_clusters:8,source_common_beta:1.,target_common_beta:1.,response_coefficient:1.,response_standard_error:0.01,residual_standard_deviation:0.01,risk_z:2.,minimum_residual:0.01,assumption_label:"Synthetic model fixture; no live calibration".into()};let obs=|source:&str,root:&str,revision:u64,at:u64,p:f64,packet:String|Observation{source:source.into(),contract_root_sha256:root.into(),packet_sha256:packet,revision,published_at_ms:at-1,received_at_ms:at,probability:p};let a=obs(&m.source,&m.source_contract_root_sha256,1,NOW-2000,0.5,sha256(b"before"));let b=obs(&m.source,&m.source_contract_root_sha256,2,NOW-1000,0.7,sha256(b"after"));let p=obs("SIG",&c.official_root_sha256,1,NOW-3000,0.355,sha256(b"sigbefore"));let q=obs("SIG",&c.official_root_sha256,2,NOW,0.355,s.books()[&c.exchange_id].source.sha256.clone());let signal=evaluate(&m,&m.sha256().unwrap(),&a,&b,&p,&q,0.,NOW).unwrap().unwrap();let _=f;(m,signal)}
#[test]fn actual_source_innovation_preserves_distinct_cash_horizon_and_requires_holding_policy_review(){let f=F::new();let s=f.bound(NOW).unwrap();let(m,signal)=innovation(&f,&s);let r=with_innovation(&f.bank,&f.scope,&s,3,&policy(),&signal,&[m.sha256().unwrap()].into(),NOW).unwrap();assert_eq!(r.lane,Lane::InformationShock);assert_eq!(r.horizon_ms,1000);assert!(!r.candidates.is_empty());assert!(!r.holding_policy_compatible);assert!(!r.prospective_economic_gate_qualified);assert!(r.candidates.iter().all(|a|a.limit_price<=485000));}
#[test]fn stale_or_mismatched_innovation_book_root_and_model_are_denied(){let f=F::new();let s=f.bound(NOW).unwrap();let(m,signal)=innovation(&f,&s);let trusted=[m.sha256().unwrap()].into();for case in ["book","root","side","expired","future"]{let mut bad=signal.clone();match case{"book"=>bad.target_packet_sha256="c".repeat(64),"root"=>bad.target_contract_root_sha256="d".repeat(64),"side"=>bad.side="NO".into(),"future"=>bad.first_available_at_ms=NOW+1,_=>bad.expires_at_ms=NOW};assert!(with_innovation(&f.bank,&f.scope,&s,3,&policy(),&bad,&trusted,NOW).is_err(),"{case}");}assert!(with_innovation(&f.bank,&f.scope,&s,3,&policy(),&signal,&Default::default(),NOW).is_err());}
#[test]fn no_quantity_or_mode_is_changed_to_manufacture_a_positive_score(){let f=F::new();let s=f.bound(NOW).unwrap();let mut p=policy();p.model_uncertainty_per_share=1000000;let r=terminal(&f.bank,&f.scope,&s,3,&p,NOW).unwrap();assert!(r.candidates.iter().all(|c|c.conditional_net_after_policy_charges<0&&c.quantity<=20&&c.gross_funding<=10_000_000));assert!(r.preferred_mode.is_none());assert!(!r.prospective_economic_gate_qualified);}
